  function dimensions(width=720){const [rw,rh]=project.ratio.split(':').map(Number);return{w:width,h:Math.round(width*rh/rw/2)*2};}
  function draw(){if(!project)return;const d=dimensions(exporting?canvas.width:720);if(canvas.width!==d.w||canvas.height!==d.h){canvas.width=d.w;canvas.height=d.h;}const at=C.sceneAt(project.scenes,time);if(!at)return;ctx.clearRect(0,0,d.w,d.h);paintScene(ctx,at.scene,at.progress,d.w,d.h,!exporting&&$('#guides').checked);if(at.index>0&&at.local<(project.transitionDuration||1.1)&&project.transition!=='cut'){const alpha=1-C.ease(at.local/(project.transitionDuration||1.1));if(project.transition==='white'){ctx.fillStyle=`rgba(255,255,255,${alpha})`;ctx.fillRect(0,0,d.w,d.h);}else{ctx.save();ctx.globalAlpha=alpha;paintScene(ctx,project.scenes[at.index-1],1,d.w,d.h,false);ctx.restore();}}$('#seek').value=time;$('#time').textContent=`${C.formatTime(time)} / ${C.formatTime(C.totalDuration(project.scenes))}`;}
  async function setupAudioElements(){for(const kind of ['music','voice']){const src=project.audio[kind],previous=kind==='music'?musicAudio:voiceAudio;if(previous?.getAttribute('src')===src)continue;if(previous){previous.pause();const old=kind==='music'?musicNode:voiceNode;old?.source.disconnect();old?.gain.disconnect();old?.bass?.disconnect();old?.treble?.disconnect();}if(!src){if(kind==='music')musicAudio=null;else voiceAudio=null;continue;}const a=new Audio(src);a.preload='auto';if(kind==='music'){musicAudio=a;musicNode=null;}else{voiceAudio=a;voiceNode=null;}await new Promise((resolve,reject)=>{a.onended=()=>{a._knownDuration=a.currentTime;};if(a.readyState>=1)resolve();else{a.addEventListener('loadedmetadata',resolve,{once:true});a.addEventListener('error',()=>reject(new Error('Ese audio no pudo abrirse. Probá con MP3 o WAV.')),{once:true});}});}}
  function connectAudio(){if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();audioDestination=audioCtx.createMediaStreamDestination();master=audioCtx.createDynamicsCompressor();master.threshold.value=-8;master.knee.value=8;master.ratio.value=4;master.connect(audioDestination);master.connect(audioCtx.destination);}if(musicAudio&&!musicNode){const source=audioCtx.createMediaElementSource(musicAudio),gain=audioCtx.createGain();source.connect(gain);gain.connect(master);musicNode={source,gain};}if(voiceAudio&&!voiceNode){const source=audioCtx.createMediaElementSource(voiceAudio),gain=audioCtx.createGain(),bass=audioCtx.createBiquadFilter(),treble=audioCtx.createBiquadFilter();bass.type='lowshelf';bass.frequency.value=180;treble.type='highshelf';treble.frequency.value=2800;source.connect(bass);bass.connect(treble);treble.connect(gain);gain.connect(master);voiceNode={source,gain,bass,treble};}for(const s of project.scenes)if(s.video){const video=asset(s.video,true);if(!videoNodes.has(video)){const source=audioCtx.createMediaElementSource(video),gain=audioCtx.createGain();source.connect(gain);gain.connect(master);videoNodes.set(video,{source,gain});}}return audioCtx.resume();}
  function syncOneAudio(audio,position,enabled){if(!audio)return;if(!enabled){audio.pause();return;}if(Number.isFinite(audio.duration)&&audio.duration>0){position=C.clamp(position,0,Math.max(0,audio.duration-.03));}if(Math.abs(audio.currentTime-position)>.25)audio.currentTime=position;if(audio.paused)audio.play().catch(()=>{});}
  function syncSound(){const a=project.audio,total=C.totalDuration(project.scenes),voicePosition=(time-a.voiceOffset)*C.clamp(a.voiceRate??1,.6,1.6),voiceActive=!!voiceAudio&&voicePosition>=0&&(voicePosition<(Number.isFinite(voiceAudio.duration)?voiceAudio.duration:(voiceAudio._knownDuration||Infinity))),fade=Math.min(1,time/.3,(total-time)/.5);if(musicAudio){const musicPosition=time*C.clamp(a.musicRate??1,.5,1.75);musicAudio.playbackRate=C.clamp(a.musicRate??1,.5,1.75);musicAudio.preservesPitch=true;const duration=Number.isFinite(musicAudio.duration)?musicAudio.duration:0,start=C.clamp(a.musicStart,0,Math.max(0,duration-.05)),end=a.musicEnd>start?Math.min(a.musicEnd,duration):duration,length=Math.max(.05,end-start),enabled=a.musicLoop||musicPosition<length;syncOneAudio(musicAudio,start+(a.musicLoop?musicPosition%length:musicPosition),enabled);if(musicNode)musicNode.gain.gain.setTargetAtTime(a.musicVolume*(a.duck&&voiceActive?.6:1)*Math.max(0,fade),audioCtx.currentTime,.03);}if(voiceAudio){voiceAudio.playbackRate=C.clamp(a.voiceRate??1,.6,1.6);voiceAudio.preservesPitch=true;}if(voiceNode){voiceNode.bass.gain.value=C.clamp(a.voiceBass??0,-12,12);voiceNode.treble.gain.value=C.clamp(a.voiceTreble??0,-12,12);}syncOneAudio(voiceAudio,Math.max(0,voicePosition),voiceActive);if(voiceNode)voiceNode.gain.gain.setTargetAtTime(a.voiceVolume*Math.max(0,fade),audioCtx.currentTime,.03);const at=C.sceneAt(project.scenes,time);for(const s of project.scenes)if(s.video){const v=asset(s.video,true),isActive=s===at?.scene;if(isActive){v.muted=!a.clipAudio;const trimStart=s.videoTrimStart||0,trimEnd=s.videoTrimEnd||v.duration,pos=s.videoTrimEnd?trimStart+Math.min(at.local,Math.max(0,trimEnd-trimStart-.03)):at.local%v.duration;if(Number.isFinite(v.duration)&&v.duration>0&&Math.abs(v.currentTime-pos)>.08)v.currentTime=pos;if(s.videoTrimEnd&&at.local>=Math.max(0,(s.videoTrimEnd-(s.videoTrimStart||0))))v.pause();else if(v.paused)v.play().catch(()=>{});}else v.pause();const node=videoNodes.get(v);if(node)node.gain.gain.value=isActive&&a.clipAudio?1:0;}for(const s of project.scenes)if(isVideoSource(s.background)){const v=asset(s.background,true),isActive=s===at?.scene;v.muted=true;if(isActive){if(Number.isFinite(v.duration)&&v.duration>0&&Math.abs(v.currentTime-at.local%v.duration)>.25)v.currentTime=at.local%v.duration;if(v.paused)v.play().catch(()=>{});}else v.pause();}}
  function stopSound(){$$('audio').forEach(a=>a.pause());musicAudio?.pause();voiceAudio?.pause();for(const value of media.values())if(value instanceof HTMLVideoElement)value.pause();}
  async function play(){if(playing||exporting)return;try{$$('audio').forEach(a=>a.pause());await prepareMedia();await connectAudio();if(time>=C.totalDuration(project.scenes)-.03)time=0;playing=true;startClock=performance.now()-time*1000;$('#play').textContent='❚❚ Pausar';tick();}catch(e){notify(e.message,'error');}}
