  let lastExportURL=null;
  async function showExportDownload(blob,name){if(lastExportURL)URL.revokeObjectURL(lastExportURL);lastExportURL=URL.createObjectURL(blob);let link=$('#lastExport');if(!link){link=document.createElement('a');link.id='lastExport';link.className='button primary';link.style.margin='6px 0';$('#previewHint').before(link);}link.href=lastExportURL;link.download=name;link.textContent='↓ Descargar último video';try{await dbAction('exports','readwrite',s=>s.put({id:project.id,blob,name,updatedAt:Date.now()}));await saveRecord();}catch(e){notify('El video está listo para descargar; no se pudo conservar una copia local.','error');}link.click();if(shareAfterExport){shareAfterExport=false;shareVideoDialog(blob,name);} }
