  function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('salmos-reels-v1',2);r.onupgradeneeded=()=>{for(const name of ['projects','posts','exports'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
