  async function loadSaved(){const all=await dbAction('projects','readonly',s=>s.getAll()),host=$('#savedProjects');host.replaceChildren();const latest=new Map();for(const p of all.sort((a,b)=>b.savedAt-a.savedAt)){const id=p.originalId||p.id;if(!latest.has(id))latest.set(id,p);}for(const p of latest.values()){const row=document.createElement('article');row.className='saved-card';const cover=new Image();cover.className='project-cover';cover.alt=p.title;cover.src=p.cover||p.scenes[0]?.thumbnail||p.scenes[0]?.final||p.scenes[0]?.base||'';const title=document.createElement('strong');title.textContent=p.title;const small=document.createElement('small');small.textContent=p.scenes.length+' escenas · '+C.formatTime(C.totalDuration(p.scenes));const actions=document.createElement('div');actions.className='project-actions';const open=document.createElement('button');open.textContent='Editar';open.onclick=()=>openSavedProject(p);cover.onclick=open.onclick;const down=document.createElement('button');down.textContent='↓ Video';down.title='Descargar video';down.onclick=()=>projectVideoAction(p,false);const share=document.createElement('button');share.textContent='Compartir';share.onclick=()=>projectVideoAction(p,true);const copy=document.createElement('button');copy.textContent='↓ Proyecto';copy.title='Descargar proyecto editable';copy.onclick=()=>download(new Blob([JSON.stringify(p)],{type:'application/json'}),(p.title||'SALMOS')+'.salmos.json');const del=document.createElement('button');del.textContent='×';del.title='Eliminar proyecto';del.onclick=async()=>{if(!confirm('¿Eliminar este proyecto guardado?'))return;await dbAction('projects','readwrite',s=>{for(const item of all)if((item.originalId||item.id)===(p.originalId||p.id))s.delete(item.id);});await dbAction('exports','readwrite',s=>s.delete(p.originalId||p.id));loadSaved();};actions.append(open,down,share,copy,del);row.append(cover,title,small,actions);host.append(row);}if(!host.childElementCount)host.textContent='Todavía no guardaste proyectos.';}

