  async function connectLocal(){try{$('#localStatus').textContent='Conectando…';const data=await(await helperFetch('/api/health')).json();if(data.version<3)throw Error('Programa anterior: usá Actualizar conexión local y abrí el archivo descargado.');localHealth=data;localReady=true;const voices=$('#ttsVoice'),previous=voices.value;voices.replaceChildren();for(const v of data.voices||[])voices.add(new Option(v.name,v.id));if([...voices.options].some(o=>o.value===previous))voices.value=previous;$('#localStatus').textContent='Conectado · '+(data.ffmpeg?'MP4 disponible':'MP4 sin instalar');$('#ttsStatus').textContent=data.tts?'Conectado. Elegí una voz, escuchá una muestra y generá el relato.':'No hay voces disponibles. Usá Actualizar conexión local para prepararlas.';notify('Programa local conectado.');return !!data.tts;}catch(e){localReady=false;$('#localStatus').textContent=e.message.includes('anterior')?e.message:'Abrí tu conexión local de SALMOS o usá Actualizar conexión local. Si Chrome pide acceso a tu red local, ese permiso conecta el editor con el programa de tu PC.';$('#ttsStatus').textContent=$('#localStatus').textContent;notify($('#localStatus').textContent,'error');return false;}}
  async function generateTts(sample=false){if(!project.narration.trim())return notify('Escribí primero el texto de la narración.','error');if(!localReady&&!await connectLocal())return;const buttons=[$('#tts'),$('#ttsSample')];buttons.forEach(b=>b.disabled=true);$('#ttsStatus').textContent=sample?'Preparando muestra…':'Generando narración…';pause();try{const text=sample?project.narration.slice(0,180):project.narration;const blob=await(await helperFetch('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,voice:$('#ttsVoice').value,pitch:Number($('#ttsPitch').value)})})).blob();const audition=$('#ttsAudition');if(audition.src.startsWith('blob:'))URL.revokeObjectURL(audition.src);audition.src=URL.createObjectURL(blob);audition.hidden=false;if(sample){await audition.play();$('#ttsStatus').textContent='Esta es una muestra de hasta 180 caracteres. No reemplazó tu narración.';}else{checkpoint();project.audio.voice=await blobData(blob);project.audio.voiceName='Relator · '+$('#ttsVoice').selectedOptions[0].textContent;await setupAudioElements();syncForm();changed();$('#ttsStatus').textContent='Narración agregada. Tocá Ver reel para escucharla con la escena y la música. Se incluye al exportar.';notify('Narración lista dentro del reel.');}}catch(e){$('#ttsStatus').textContent=e.message;notify(e.message,'error');}finally{buttons.forEach(b=>b.disabled=false);}}
  async function toggleRecord(){if(recording){recording.stop();return;}if(exporting)return;pause();try{recordStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recording=new MediaRecorder(recordStream,type?{mimeType:type}:{});const chunks=[];recording.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recording.onstop=async()=>{const mime=recording.mimeType;recordStream.getTracks().forEach(t=>t.stop());recording=null;recordStream=null;$('#record').textContent='● Grabar mi voz';$('#recordState').textContent='Grabación terminada.';try{checkpoint();project.audio.voice=await blobData(new Blob(chunks,{type:mime}));project.audio.voiceName='Mi voz · '+new Date().toLocaleTimeString('es-AR');await setupAudioElements();syncForm();changed();}catch(e){notify(e.message,'error');}};recording.onerror=()=>{recordStream?.getTracks().forEach(t=>t.stop());recording=null;$('#record').textContent='● Grabar mi voz';notify('La grabación se interrumpió. Revisá el permiso del micrófono.','error');};recording.start(250);$('#record').textContent='■ Terminar grabación';$('#recordState').textContent='Grabando… hablá cerca del micrófono.';}catch(e){notify('No se pudo abrir el micrófono. Permití su uso en el navegador o subí una grabación.','error');}}
  async function doExport(){if(musicTrial)return notify('Terminá la prueba musical y elegí una pista antes de exportar.');if(exporting||recording)return notify('Terminá la grabación antes de exportar.','error');const desired=$('#exportFormat').value,width=Number($('#quality').value),mp4='video/mp4;codecs=avc1.42E01E,mp4a.40.2',mp4Only='video/mp4;codecs=avc1.42001E,mp4a.40.2',webm='video/webm;codecs=vp9,opus',fallback='video/webm;codecs=vp8,opus';if(!window.MediaRecorder||!canvas.captureStream)return notify('Este navegador no permite exportar video. Usá una versión actual de Chrome o Edge.','error');const hasAudio=!!(project.audio.music||project.audio.voice||project.audio.clipAudio||(project.audio.sfx||[]).length);const mp4Type=[mp4,mp4Only,...(hasAudio?[]:['video/mp4;codecs=avc1.42E01E'])].find(t=>MediaRecorder.isTypeSupported(t));if(desired==='mp4'&&!mp4Type&&(!localReady||!localHealth?.ffmpeg)){setTab('audio');$('#exportDialog').close();return notify('Para MP4 en este navegador, abrí el programa local y tocá «Conectar programa local». También podés exportar WebM.','error');}const mime=desired!=='webm'&&mp4Type?mp4Type:[webm,fallback,'video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)return notify('No hay un formato de grabación disponible en este navegador.','error');pause();$('#exportDialog').close();const oldTime=time;let stream,recorder;try{await prepareMedia();if(project.scenes.some(s=>s.giphy&&!giphyRuntime.has(s.id)))throw Error('Conectá GIPHY para cargar el fondo de este proyecto.');await connectAudio();exporting=true;cancelled=false;document.body.classList.add('exporting');$('#busyOverlay').hidden=false;$('#busyText').textContent='Creando tu video…';$('#exportProgress').value=0;const d=dimensions(width);canvas.width=d.w;canvas.height=d.h;time=0;draw();stream=canvas.captureStream(30);if(project.audio.music||project.audio.voice||project.audio.clipAudio||(project.audio.sfx||[]).length)for(const track of audioDestination.stream.getAudioTracks())stream.addTrack(track.clone());const chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:width>=1080?12000000:width>=720?6500000:3500000,audioBitsPerSecond:192000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};const stopped=new Promise((resolve,reject)=>{recorder.onstop=resolve;recorder.onerror=e=>reject(new Error(e.error?.message||'Falló la grabación.'));});recorder.start(500);const start=performance.now()+500,duration=C.totalDuration(project.scenes);await new Promise(resolve=>{function frame(){if(cancelled){resolve();return;}time=Math.max(0,Math.min(duration,(performance.now()-start)/1000));if(performance.now()>=start)syncSound();draw();$('#exportProgress').value=time/duration;if(performance.now()-start>=(duration*1000+250)){resolve();return;}requestAnimationFrame(frame);}requestAnimationFrame(frame);});stopSound();if(recorder.state!=='inactive')recorder.stop();await stopped;if(cancelled)return;let blob=new Blob(chunks,{type:recorder.mimeType}),extension=recorder.mimeType.startsWith('video/mp4')?'mp4':'webm';if(desired==='mp4'&&extension!=='mp4'){$('#busyText').textContent='Convirtiendo a MP4 en tu computadora…';blob=await(await helperFetch('/api/convert',{method:'POST',headers:{'Content-Type':blob.type},body:blob})).blob();extension='mp4';}await showExportDownload(blob,filename()+'.'+extension);notify(`Video ${extension.toUpperCase()} descargado con ${project.scenes.length} escena(s).`);}catch(e){notify(e.message||'No se pudo exportar. Probá con calidad 540 o 720.','error');}finally{stopSound();if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());exporting=false;$('#busyOverlay').hidden=true;document.body.classList.remove('exporting');time=oldTime;draw();syncUndo();}}
  function updatePrompt(){const phrases={subtle:'The model makes a very subtle natural posture adjustment, with gentle breathing. Keep the camera almost still.',camera:'Very slow smooth camera push-in toward the garment print. The model remains still.',fabric:'A very gentle breeze moves the fabric slightly. The model stays in the same pose.',product:'A subtle elegant camera movement presents the product. Keep its shape, proportions and surface unchanged.'};$('#aiPrompt').value=`${phrases[$('#aiMotion').value]} Preserve the exact garment color, printed artwork, lettering, face, body and background. No new objects, no added text, no redesign, no camera cuts. Short 2-second product advertisement.`;}
  let requestCounter=0;const requests=new Map();
  function requestParent(action,data={}){if(parent===window)return Promise.reject(new Error('Abrí este estudio desde el panel SALMOS para traer el producto. También podés cargar los archivos manualmente.'));return new Promise((resolve,reject)=>{const id='marketing-'+(++requestCounter);requests.set(id,{resolve,reject});parent.postMessage({type:'salmos-marketing-request',id,action,...data},location.origin);setTimeout(()=>{if(requests.has(id)){requests.delete(id);reject(new Error('No llegó la composición. Volvé a Producción, elegí la vista y tocá «Crear reel».'));}},60000);});}
  window.addEventListener('message',async event=>{if(event.source!==parent||event.origin!==location.origin)return;const data=event.data;if(data?.type==='salmos-marketing-pause'){pause();if(recording)recording.stop();if(exporting)cancelled=true;return;}if(data?.type==='salmos-marketing-response'){const item=requests.get(data.id);if(!item)return;requests.delete(data.id);if(data.error)item.reject(new Error(data.error));else item.resolve(data.payload);}if(data?.type==='salmos-marketing-composition')try{await importPayload(data.payload);}catch(e){notify(e.message,'error');}});
  let editingStamp=false,focusPicking=false,textPicking=false,demoCache;
  const isVideoSource=src=>/^data:video\//i.test(src||'');
  async function productFrame(){pause();await prepareMedia();const s=current(),im=s.final?asset(s.final):sceneImage(s);if(!im)throw new Error('Cargá una foto del producto antes de prepararla para IA.');const source=im.frame?im.frame(time):im,iw=im.videoWidth||im.naturalWidth||im.width,ih=im.videoHeight||im.naturalHeight||im.height,k=Math.min(1,2048/Math.max(iw,ih)),out=document.createElement('canvas');out.width=Math.round(iw*k);out.height=Math.round(ih*k);const c=out.getContext('2d');c.drawImage(source,0,0,out.width,out.height);if(s.stamp&&!s.final){const stamp=asset(s.stamp),p=s.placement,w=p.w*out.width,h=w*stamp.height/stamp.width;c.save();c.translate(p.x*out.width+w/2,p.y*out.height+h/2);c.rotate(p.rotation*Math.PI/180);c.drawImage(stamp,-w/2,-h/2,w,h);c.restore();}await new Promise(resolve=>out.toBlob(blob=>{if(blob)download(blob,filename()+'-producto-para-IA.png');resolve();},'image/png'));}
  function demoAssets(){if(demoCache)return demoCache;const base=document.createElement('canvas');base.width=720;base.height=1000;demoProduct(base.getContext('2d'),{x:0,y:0,w:720,h:1000});const stamp=document.createElement('canvas');stamp.width=300;stamp.height=210;demoStamp(stamp.getContext('2d'),{x:0,y:0,w:300,h:210});return demoCache={base:base.toDataURL(),stamp:stamp.toDataURL(),baseName:'Prenda de demostración',stampName:'Estampa de demostración'};}
  function normalizeProject(){project.audio={voiceRate:1,voiceBass:0,voiceTreble:0,...project.audio};for(const s of project.scenes){if(s.demo&&!s.base&&!s.final&&!s.video)Object.assign(s,demoAssets());s.duration=C.clamp(s.duration,2,30);s.placement||={x:.31,y:.27,w:.38,rotation:0};migrateScene(s);}return project;}
  function drawStampBox(c,b,rotation){const pts=T.points(b,rotation),cssWidth=canvas.getBoundingClientRect().width||300,k=720/cssWidth;c.save();c.strokeStyle='#b8387c';c.lineWidth=1.4*k;c.beginPath();pts.slice(0,4).forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();c.stroke();const mid={x:(pts[0].x+pts[1].x)/2,y:(pts[0].y+pts[1].y)/2};c.beginPath();c.moveTo(mid.x,mid.y);c.lineTo(pts[4].x,pts[4].y);c.stroke();pts.forEach((p,i)=>{c.fillStyle=i===4?'#ad3973':'#fff4fa';c.beginPath();c.arc(p.x,p.y,(i===4?8:6)*k,0,Math.PI*2);c.fill();c.stroke();if(i===4){c.fillStyle='white';c.font=`${13*k}px Arial`;c.textAlign='center';c.textBaseline='middle';c.fillText('↻',p.x,p.y);}});c.restore();}
  function paintBackdrop(c,s,seconds,W,H){if(!s.bgMotion)return;if(['bokeh','waves','confetti'].includes(s.bgMotion)){c.save();for(let i=0;i<22;i++){const x=(i*163+Math.sin(seconds*.35+i)*55)%W,y=((i*127-seconds*(48+i%6*9))%H+H)%H;c.fillStyle=['#e994bb55','#e8c66e55','#91cbd955','#ab96dc55'][i%4];if(s.bgMotion==='bokeh'){const r=18+i%5*12,g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,c.fillStyle);g.addColorStop(1,'#ffffff00');c.fillStyle=g;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();}else if(s.bgMotion==='confetti'){c.save();c.translate(x,y);c.rotate(seconds*.5+i);c.fillRect(-4,-10,8,20);c.restore();}else{c.strokeStyle=c.fillStyle;c.lineWidth=4;c.beginPath();for(let q=0;q<=W;q+=12){const yy=y+Math.sin(q/130+seconds+i)*30;q?c.lineTo(q,yy):c.moveTo(q,yy);}c.stroke();}}c.restore();return;}const kinds={hearts:'♡',petals:'❀',stars:'✦'};c.save();c.fillStyle=project.palette==='cream'?'#bc759c':'#c95b93bb';c.textAlign='center';for(let i=0;i<32;i++){const x=((i*173+Math.sin(seconds*.4+i)*20)%W+W)%W,y=((i*241-seconds*(65+i%4*18))%H+H)%H;c.save();c.translate(x,y);c.rotate(Math.sin(i+seconds*.3)*.3);c.font=`${32+i%4*18}px Georgia`;c.fillText(kinds[s.bgMotion]||'✦',0,0);c.restore();}c.restore();}
  function syncExtraForm(){syncComponents();const s=current();$('#backgroundInfo').textContent=s.background?(s.backgroundName?'Fondo de Producción · '+s.backgroundName:'Fondo cargado.'):s.bgMotion?'Fondo animado · '+s.bgMotion:'Se usa el color elegido.';$('#placementHelp').textContent='';if(voiceAudio){voiceAudio.playbackRate=C.clamp(project.audio.voiceRate,.6,1.6);voiceAudio.preservesPitch=true;}$('#voiceListen').playbackRate=C.clamp(project.audio.voiceRate,.6,1.6);}
  function localPointer(event,geometry=lastGeometry){const rect=canvas.getBoundingClientRect(),pixel={x:(event.clientX-rect.left)*canvas.width/rect.width,y:(event.clientY-rect.top)*canvas.height/rect.height};return{pixel,point:geometry.matrix.inverse().transformPoint(pixel),rect};}
  function handleHit(event){if(!lastGeometry||!current().stamp||current().final)return -1;const {pixel,rect}=localPointer(event);return T.points(lastGeometry.b,current().placement.rotation).findIndex(p=>{const screen=lastGeometry.matrix.transformPoint(p);return Math.hypot((screen.x-pixel.x)*rect.width/canvas.width,(screen.y-pixel.y)*rect.height/canvas.height)<=13;});}
  function backgroundShelf(){const host=$('#backgroundShelf');host.replaceChildren();for(const [name,motion,palette] of [['♡ Rosa con corazones','hearts','pink'],['❀ Pétalos','petals','pink'],['✦ Brillos','stars','pink'],['◌ Luces suaves','bokeh','blue'],['〰 Ondas','waves','lilac'],['▧ Confeti','confetti','cream'],['Crema suave','','cream'],['Rosa liso','','pink'],['Bordó','','red']]){const b=document.createElement('button'),swatch=document.createElement('span');swatch.className='swatch';swatch.style.background=`linear-gradient(135deg,${C.palettes[palette][0]},${C.palettes[palette][1]})`;swatch.textContent=name.split(' ')[0];b.append(swatch,document.createTextNode(name));b.onclick=()=>{checkpoint();current().background=null;delete current().giphy;current().bgMotion=motion;project.palette=palette;project.textColor=C.palettes[palette][3];syncForm();changed();};host.append(b);}}
  async function salmosBackgrounds(){let dialog;try{const entries=await requestParent('backgrounds');dialog=document.createElement('dialog');const heading=document.createElement('h2');heading.textContent='❀ Tus fondos de SALMOS';const search=document.createElement('input');search.type='search';search.placeholder='Buscar un fondo…';const grid=document.createElement('div');grid.className='background-shelf';grid.style.cssText='max-height:60vh;overflow:auto;margin:12px 0';const render=()=>{grid.replaceChildren();for(const item of entries.filter(v=>v.name.toLowerCase().includes(search.value.toLowerCase())).slice(0,90)){const b=document.createElement('button'),im=document.createElement('img');im.crossOrigin='use-credentials';im.src=item.url;im.loading='lazy';im.alt=item.name;b.append(im,document.createTextNode(item.name));b.onclick=async()=>{b.disabled=true;try{const payload=await requestParent('background',{assetId:item.id}),data=await blobData(payload.blob);await asset(data)._ready;checkpoint();current().background=data;current().bgMotion='';syncForm();changed();dialog.close();}catch(e){notify(e.message,'error');b.disabled=false;}};grid.append(b);}if(!grid.childElementCount)grid.textContent='No encontré fondos con ese nombre.';};search.oninput=render;const close=document.createElement('button');close.textContent='Volver';close.onclick=()=>dialog.close();dialog.append(heading,search,grid,close);dialog.onclose=()=>dialog.remove();document.body.append(dialog);render();dialog.showModal();}catch(e){dialog?.remove();notify(parent===window?'Los fondos guardados se ven al abrir Marketing dentro de SALMOS. Como todavía estás probando el ZIP, usá los fondos incluidos o subí uno propio.':e.message,'error');}}
  function buildStories(){const host=$('#storyCards');host.replaceChildren();const filter=$('#storyFilter').value,query=$('#storySearch').value.toLocaleLowerCase('es');for(const story of window.SalmosStories.filter(s=>(filter==='all'||(filter==='ai'?s.kind.includes('IA +'):!s.kind.includes('IA +')))&&[s.title,s.need].join(' ').toLocaleLowerCase('es').includes(query))){const card=document.createElement('article');card.className='story-card';const tag=document.createElement('span');tag.className='tag';tag.textContent=story.kind+' · '+story.shots.length+' tomas';const h=document.createElement('h2');h.textContent=story.icon+' '+story.title;const need=document.createElement('p');need.textContent=story.need;const list=document.createElement('ol');for(const shot of story.shots){const item=document.createElement('li'),title=document.createElement('strong');title.textContent=shot.title+' · ';item.append(title,document.createTextNode(shot.direction));if(shot.prompt){const d=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Indicación de IA';const text=document.createElement('textarea');text.readOnly=true;text.value=shot.prompt;d.append(summary,text);item.append(d);}list.append(item);}const use=document.createElement('button');use.className='primary';use.textContent='Cargar guion por escenas';use.onclick=async()=>{pause();checkpoint();await saveRecord().catch(()=>{});const source=structuredClone(current());project.id=C.uid();project.title=story.title;project.scenes=story.shots.map((shot,i)=>({...structuredClone(source),id:C.uid(),shotTitle:shot.title,template:shot.template,duration:4,headline:'',detail:'',cta:i===story.shots.length-1?'Consultanos por tu diseño':'',video:null,direction:shot.direction,method:shot.method,aiPrompt:shot.prompt,effect:{start:.1,length:1.5,soft:.6,zoom:shot.template==='zoom'?3:1.15,count:.6},focus:null,textAnchor:null}));for(const scene of project.scenes){scene.components=scene.components.filter(l=>l.kind!=='text');if(scene.cta){const l=textComponent(scene.cta,{y:.9});scene.components.push(l);await renderTextLayer(l);scene.cta='';}}if(story.id==='cabina'&&project.scenes[0].base){Object.assign(project.scenes[0],{stamp:null,final:null,components:[],demoBlank:true});project.scenes[1].headline='SALMOS';}active=0;time=0;editingStamp=false;await prepareMedia();syncForm();changed();setTab('editor');notify(`Guion de ${story.shots.length} escenas creado. Las tomas indicadas como IA necesitan sus clips; cargalos en cada escena.`);};card.append(tag,h,need,list,use);host.append(card);}}
